    private void applyMapStyle(){
        if(map==null)return;String style=prefs==null?"osm":prefs.getString("map_style","osm");
        if("humanitarian".equals(style))map.setTileSource(new XYTileSource("OSM Humanitaire",0,19,256,".png",new String[]{"https://a.tile.openstreetmap.fr/hot/","https://b.tile.openstreetmap.fr/hot/","https://c.tile.openstreetmap.fr/hot/"}));
        else if("cyclosm".equals(style))map.setTileSource(new XYTileSource("CyclOSM",0,20,256,".png",new String[]{"https://a.tile-cyclosm.openstreetmap.fr/cyclosm/","https://b.tile-cyclosm.openstreetmap.fr/cyclosm/","https://c.tile-cyclosm.openstreetmap.fr/cyclosm/"}));
        else if("topo".equals(style))map.setTileSource(new XYTileSource("OpenTopoMap",0,17,256,".png",new String[]{"https://a.tile.opentopomap.org/","https://b.tile.opentopomap.org/","https://c.tile.opentopomap.org/"}));
        else map.setTileSource(TileSourceFactory.MAPNIK);
        map.setTilesScaledToDpi(prefs==null||prefs.getBoolean("tiles_scaled",true));map.setBuiltInZoomControls(prefs!=null&&prefs.getBoolean("zoom_controls",false));map.invalidate();
    }

    private void applyPositionIcon(){
        if(me==null)return;Bitmap icon=createPositionIcon(prefs==null?"Camion":prefs.getString("position_icon","Camion"));me.setDrawAccuracyEnabled(prefs==null||prefs.getBoolean("position_accuracy",true));me.setPersonIcon(icon);me.setDirectionArrow(icon,icon);me.setPersonHotspot(icon.getWidth()/2f,icon.getHeight()/2f);if(map!=null)map.invalidate();
    }
