        TextView add=pill("＋ Ajouter une journée",accent);add.setOnClickListener(v->showHoursEntrySheet());LinearLayout.LayoutParams ap=new LinearLayout.LayoutParams(-1,dp(50));ap.topMargin=dp(11);ap.bottomMargin=dp(10);p.addView(add,ap);
        for(WorkHoursStore.Entry e:entries){LinearLayout card=new LinearLayout(this);card.setOrientation(LinearLayout.VERTICAL);card.setPadding(dp(14),dp(12),dp(14),dp(12));card.setBackground(glass(SURFACE,20));LinearLayout top=new LinearLayout(this);top.setGravity(Gravity.CENTER_VERTICAL);LinearLayout date=new LinearLayout(this);date.setOrientation(LinearLayout.VERTICAL);date.addView(text(dayLabel(e.date),15,Typeface.BOLD,TEXT));date.addView(text(e.date,10,Typeface.NORMAL,MUTED));top.addView(date,new LinearLayout.LayoutParams(0,-2,1));TextView net=pill(formatMinutes(e.netMinutes()),Color.argb(150,Color.red(BLUE),Color.green(BLUE),Color.blue(BLUE)));top.addView(net,new LinearLayout.LayoutParams(dp(86),dp(36)));card.addView(top);LinearLayout st=new LinearLayout(this);st.setPadding(0,dp(10),0,0);st.addView(summaryStat("DÉBUT",timeLabel(e.startMinutes)),new LinearLayout.LayoutParams(0,-2,1));st.addView(summaryStat("FIN",timeLabel(e.endMinutes)),new LinearLayout.LayoutParams(0,-2,1));st.addView(summaryStat("PAUSE",e.pauseMinutes+" min"),new LinearLayout.LayoutParams(0,-2,1));card.addView(st);TextView del=text("Supprimer",11,Typeface.BOLD,RED);del.setGravity(Gravity.END);del.setPadding(0,dp(8),0,0);del.setOnClickListener(v->{hoursStore.delete(e.id);showTab("hours",false);});card.addView(del);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.topMargin=dp(8);p.addView(card,lp);}sv.addView(p);return sv;
