    private View choiceRow(String title,String key,int[] values,String[] labels,int def,Runnable changed){int cur=prefs.getInt(key,def),idx=0;for(int i=0;i<values.length;i++)if(values[i]==cur){idx=i;break;}final int selected=idx;LinearLayout row=settingsRow(title,labels[selected]);row.setOnClickListener(v->new AlertDialog.Builder(this).setTitle(title).setSingleChoiceItems(labels,selected,(d,w)->{prefs.edit().putInt(key,values[w]).apply();d.dismiss();if(changed!=null)changed.run();showTab("settings",false);}).show());return row;}
    private View stringChoiceRow(String title,String key,String[] values,String[] labels,String def,Runnable changed){String cur=prefs.getString(key,def);int found=0;for(int i=0;i<values.length;i++)if(values[i].equals(cur)){found=i;break;}final int idx=found;LinearLayout row=settingsRow(title,labels[idx]);row.setOnClickListener(v->new AlertDialog.Builder(this).setTitle(title).setSingleChoiceItems(labels,idx,(d,w)->{prefs.edit().putString(key,values[w]).apply();d.dismiss();if(changed!=null)changed.run();showTab("settings",false);}).show());return row;}
    private LinearLayout settingsRow(String title,String value){LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(dp(14),dp(12),dp(12),dp(12));row.setBackground(glass(SURFACE,20));LinearLayout tx=new LinearLayout(this);tx.setOrientation(LinearLayout.VERTICAL);tx.addView(text(title,14,Typeface.BOLD,TEXT));tx.addView(text(value,11,Typeface.NORMAL,MUTED));row.addView(tx,new LinearLayout.LayoutParams(0,-2,1));TextView arrow=text("⌄",18,Typeface.BOLD,MUTED);arrow.setGravity(Gravity.CENTER);row.addView(arrow,new LinearLayout.LayoutParams(dp(28),dp(34)));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.topMargin=dp(8);row.setLayoutParams(lp);return row;}
    private View toggleRow(String title,String sub,String key,boolean def,Runnable changed){LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(dp(14),dp(12),dp(12),dp(12));row.setBackground(glass(SURFACE,20));LinearLayout tx=new LinearLayout(this);tx.setOrientation(LinearLayout.VERTICAL);tx.addView(text(title,14,Typeface.BOLD,TEXT));tx.addView(text(sub,11,Typeface.NORMAL,MUTED));row.addView(tx,new LinearLayout.LayoutParams(0,-2,1));TextView state=toggleCapsule(prefs.getBoolean(key,def));row.addView(state,new LinearLayout.LayoutParams(dp(54),dp(32)));row.setOnClickListener(v->{press(v);boolean on=!prefs.getBoolean(key,def);prefs.edit().putBoolean(key,on).apply();state.setText(on?"ON":"OFF");state.setTextColor(on?BG:MUTED);state.setBackground(glass(on?accent:SURFACE2,16));if(changed!=null)changed.run();});LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.topMargin=dp(8);row.setLayoutParams(lp);return row;}
    private TextView toggleCapsule(boolean on){TextView t=text(on?"ON":"OFF",10,Typeface.BOLD,on?BG:MUTED);t.setGravity(Gravity.CENTER);t.setBackground(glass(on?accent:SURFACE2,16));return t;}

    private void startRecording(){recordingPoints.clear();recordingEvents.clear();recordedDistance=0;paused=false;pausedTotal=0;recordingStarted=System.currentTimeMillis();recording=true;if(lastLocation!=null)addRecordingFix(lastLocation,true);showTab("record",false);}
    private void finishRecording(){if(recordingPoints.size()<2){toast("Pas assez de points GPS");return;}recording=false;paused=false;setFlagEnabled(false);toast("Optimisation du tracé…");List<RouteStore.Point> p=new ArrayList<>(recordingPoints);List<RouteStore.Event> e=new ArrayList<>(recordingEvents);long started=recordingStarted;new Thread(()->{File f=store.createRoute(p,e,started);store.clearDraft();runOnUiThread(()->{recordingPoints.clear();recordingEvents.clear();recordedDistance=0;toast(f==null?"Sauvegarde impossible":"Tournée sauvegardée");if(f!=null)prefs.edit().putString("gpx_lab_file",f.getName()).apply();showTab("routes",false);});},"routix-save").start();}
    private void togglePause(){if(!recording)return;if(!paused){paused=true;pauseStarted=System.currentTimeMillis();}else{paused=false;pausedTotal+=System.currentTimeMillis()-pauseStarted;if(lastLocation!=null)addRecordingFix(lastLocation,true);}showTab("record",false);}
    private void addEvent(String type,String label){if(!recording||paused||lastLocation==null){toast("Enregistrement GPS requis");return;}recordingEvents.add(new RouteStore.Event(type,label,lastLocation.getLatitude(),lastLocation.getLongitude(),System.currentTimeMillis(),lastLocation.hasAccuracy()?lastLocation.getAccuracy():0));press("REVERSE".equals(type)?reverseButton:twoSidesButton);refreshRecord();}
    private void addGuidanceFlag(String type,String label){if(!guiding||guidingRoute==null||lastLocation==null){toast("GPS ou tournée indisponible");return;}List<RouteStore.Event> e=new ArrayList<>(guidingRoute.events);e.add(new RouteStore.Event(type,label,lastLocation.getLatitude(),lastLocation.getLongitude(),System.currentTimeMillis(),lastLocation.hasAccuracy()?lastLocation.getAccuracy():0));boolean ok=store.writeGpx(guidingRoute.file,guidingRoute.points,e,guidingRoute.firstTime>0?guidingRoute.firstTime:System.currentTimeMillis(),store.displayName(guidingRoute.file));if(ok){guidingRoute=store.parse(guidingRoute.file);toast("REVERSE".equals(type)?"Marche arrière ajoutée":"2 côtés ajouté");}else toast("Impossible d’ajouter le repère");}
    private void addRecordingFix(Location l,boolean force){if(!recording||paused||l==null)return;if(l.hasAccuracy()&&l.getAccuracy()>prefs.getInt("record_accuracy",45))return;RouteStore.Point p=new RouteStore.Point(l.getLatitude(),l.getLongitude(),l.getTime()>0?l.getTime():System.currentTimeMillis(),l.hasAccuracy()?l.getAccuracy():0);if(!recordingPoints.isEmpty()){RouteStore.Point prev=recordingPoints.get(recordingPoints.size()-1);double d=RouteNormalizer.distanceM(prev,p);if(!force&&d<prefs.getInt("record_spacing",2))return;if(d<250)recordedDistance+=d;}recordingPoints.add(p);if(System.currentTimeMillis()-lastDraftAt>prefs.getInt("draft_seconds",15)*1000L){lastDraftAt=System.currentTimeMillis();store.saveDraft(recordingPoints,recordingEvents,recordingStarted);}refreshRecord();}
    private void refreshRecord(){if(recordDistance!=null)recordDistance.setText(formatDistance(recordedDistance)+"\nDISTANCE");if(recordPoints!=null)recordPoints.setText(recordingPoints.size()+"\nPOINTS");if(recordEvents!=null)recordEvents.setText(recordingEvents.size()+"\nREPÈRES");}
    private void setFlagEnabled(boolean on){for(TextView t:new TextView[]{reverseButton,twoSidesButton,pauseButton})if(t!=null){t.setEnabled(on);t.setAlpha(on?1:.38f);}}
    private void offerDraftRecovery(){RouteStore.Summary d=store.draftSummary();new AlertDialog.Builder(this).setTitle("Tournée interrompue").setMessage(d.points.size()+" points peuvent être récupérés.").setNegativeButton("Ignorer",(x,w)->store.clearDraft()).setPositiveButton("Récupérer",(x,w)->{recordingPoints.clear();recordingPoints.addAll(d.points);recordingEvents.clear();recordingEvents.addAll(d.events);recordedDistance=d.distanceM;recordingStarted=d.firstTime>0?d.firstTime:System.currentTimeMillis();recording=true;paused=false;showTab("record",true);}).show();}

    private void importGpx(){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("*/*");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,IMPORT_GPX);}
    @Override protected void onActivityResult(int r,int result,Intent data){super.onActivityResult(r,result,data);if(r==IMPORT_GPX&&result==RESULT_OK&&data!=null&&data.getData()!=null){Uri u=data.getData();toast("Analyse du GPX…");new Thread(()->{File f=store.importGpx(u);runOnUiThread(()->{toast(f==null?"Import impossible":"GPX importé et optimisé");if(f!=null)prefs.edit().putString("gpx_lab_file",f.getName()).apply();showTab(f==null?"routes":"gpxlab",false);});},"routix-import").start();}}

    private void startGuidance(RouteStore.Summary s){
        if(s==null||s.points.size()<2){toast("Trace insuffisante");return;}guidanceSession++;guidanceStartResolved=false;approachingStart=false;clearApproachRoute();List<GuidanceEngine.Point> p=new ArrayList<>();for(RouteStore.Point q:s.points)p.add(new GuidanceEngine.Point(q.lat,q.lon));List<GuidanceEngine.Event> e=new ArrayList<>();for(RouteStore.Event q:s.events)e.add(new GuidanceEngine.Event(q.type,q.label,q.lat,q.lon));guidance=new GuidanceEngine(p,e);guidance.setOffRouteThreshold(prefs.getInt("offroute_m",45));guidingRoute=s;guiding=true;guidanceCameraFollow=true;showTab("map",true);drawRemaining(null);if(lastLocation!=null)resolveGuidanceStart(lastLocation);else{if(guideTitle!=null)guideTitle.setText("GPS en attente");if(guideSubtitle!=null)guideSubtitle.setText("Routix démarrera dès qu’une position fiable sera disponible.");}
    }
    private void resolveGuidanceStart(Location l){if(!guiding||guidance==null||guidingRoute==null||guidanceStartResolved)return;guidanceStartResolved=true;RouteStore.Point first=guidingRoute.points.get(0);float[] dd=new float[1];Location.distanceBetween(l.getLatitude(),l.getLongitude(),first.lat,first.lon,dd);if(prefs.getBoolean("guide_to_start",true)&&dd[0]>70){approachingStart=true;requestApproachRoute(l,new GeoPoint(first.lat,first.lon));if(guideTitle!=null)guideTitle.setText("Vers le départ");if(guideSubtitle!=null)guideSubtitle.setText("Calcul de l’itinéraire routier…");}else{if(prefs.getBoolean("start_nearest",false))guidance.reposition(l.getLatitude(),l.getLongitude());else guidance.reset();updateRouteGuidance(l);}}
    private void requestApproachRoute(Location from,GeoPoint target){
        final long session=guidanceSession;approachInstruction="Calcul de l’itinéraire routier…";new Thread(()->{List<GeoPoint> pts=new ArrayList<>();String instruction="Suis la ligne bleue jusqu’au départ";try{String q=String.format(Locale.US,"https://router.project-osrm.org/route/v1/driving/%.6f,%.6f;%.6f,%.6f?overview=full&geometries=geojson&steps=true&alternatives=false",from.getLongitude(),from.getLatitude(),target.getLongitude(),target.getLatitude());HttpURLConnection c=(HttpURLConnection)new URL(q).openConnection();c.setConnectTimeout(7000);c.setReadTimeout(9000);c.setRequestProperty("User-Agent",getPackageName()+" Routix/3.1");BufferedReader br=new BufferedReader(new InputStreamReader(c.getInputStream()));StringBuilder b=new StringBuilder();String line;while((line=br.readLine())!=null)b.append(line);br.close();JSONObject json=new JSONObject(b.toString());JSONArray routes=json.optJSONArray("routes");if(routes!=null&&routes.length()>0){JSONObject route=routes.getJSONObject(0);JSONArray coords=route.getJSONObject("geometry").getJSONArray("coordinates");for(int i=0;i<coords.length();i++){JSONArray x=coords.getJSONArray(i);pts.add(new GeoPoint(x.getDouble(1),x.getDouble(0)));}JSONArray legs=route.optJSONArray("legs");if(legs!=null&&legs.length()>0){JSONArray steps=legs.getJSONObject(0).optJSONArray("steps");if(steps!=null&&steps.length()>1){JSONObject st=steps.getJSONObject(1);String name=st.optString("name","");if(!name.isEmpty())instruction="Continue sur "+name;}}}}catch(Exception ignored){}if(pts.size()<2){pts.clear();pts.add(new GeoPoint(from.getLatitude(),from.getLongitude()));pts.add(target);instruction="Itinéraire routier indisponible • cap direct vers le départ";}List<GeoPoint> finalPts=pts;String finalInstruction=instruction;runOnUiThread(()->{if(!guiding||!approachingStart||session!=guidanceSession)return;clearApproachRoute();approachingStart=true;approachInstruction=finalInstruction;approachPoints.addAll(finalPts);List<GuidanceEngine.Point> enginePts=new ArrayList<>();for(GeoPoint p:finalPts)enginePts.add(new GuidanceEngine.Point(p.getLatitude(),p.getLongitude()));approachGuidance=new GuidanceEngine(enginePts,Collections.emptyList());approachGuidance.reposition(from.getLatitude(),from.getLongitude());approachLine=new Polyline();approachLine.getOutlinePaint().setColor(BLUE);approachLine.getOutlinePaint().setStrokeWidth(dp(Math.max(7,prefs.getInt("route_width",10))));approachLine.getOutlinePaint().setStrokeCap(Paint.Cap.ROUND);approachLine.setPoints(finalPts);int idx=Math.max(0,map.getOverlays().indexOf(routeArrows));map.getOverlays().add(idx,approachLine);routeArrows.setPoints(finalPts);if(guideTitle!=null)guideTitle.setText("Vers le départ");if(guideSubtitle!=null)guideSubtitle.setText(approachInstruction);try{map.zoomToBoundingBox(approachLine.getBounds(),true,dp(90));}catch(Exception ignored){}if(lastLocation!=null)updateApproachGuidance(lastLocation);map.invalidate();});},"routix-approach").start();
    }
    private void updateApproachGuidance(Location l){if(!approachingStart||guidingRoute==null)return;RouteStore.Point first=guidingRoute.points.get(0);float[] d=new float[1];Location.distanceBetween(l.getLatitude(),l.getLongitude(),first.lat,first.lon,d);if(d[0]<=30){approachingStart=false;clearApproachRoute();guidance.reset();toast("Départ rejoint • guidage de tournée actif");showTab("map",false);updateRouteGuidance(l);return;}double remaining=d[0];GuidanceEngine.State state=null;if(approachGuidance!=null){state=approachGuidance.update(l.getLatitude(),l.getLongitude(),l.getTime()>0?l.getTime():System.currentTimeMillis(),l.hasAccuracy()?l.getAccuracy():8);remaining=state.remainingM;drawApproachRemaining(state);}if(guideTitle!=null)guideTitle.setText("Vers le départ");if(guideSubtitle!=null)guideSubtitle.setText(approachInstruction);if(guideDistance!=null)guideDistance.setText(formatDistance(remaining)+"\nJUSQU’AU DÉPART");if(guideProgress!=null)guideProgress.setText("↗\nDÉPART");followCamera(l);}
    private void drawApproachRemaining(GuidanceEngine.State state){if(approachLine==null||approachPoints.isEmpty())return;int start=state==null?0:Math.max(0,Math.min(approachPoints.size()-2,state.nearestIndex));List<GeoPoint> pts=new ArrayList<>();if(state!=null&&Double.isFinite(state.position.lat))pts.add(new GeoPoint(state.position.lat,state.position.lon));for(int i=start+1;i<approachPoints.size();i++)pts.add(approachPoints.get(i));approachLine.setPoints(pts);if(prefs.getBoolean("route_arrows",true))routeArrows.setPoints(pts);map.invalidate();}
    private void clearApproachRoute(){approachGuidance=null;approachPoints.clear();if(approachLine!=null&&map!=null){map.getOverlays().remove(approachLine);approachLine=null;map.invalidate();}}
    private void updateRouteGuidance(Location l){if(!guiding||guidance==null)return;GuidanceEngine.State s=guidance.update(l.getLatitude(),l.getLongitude(),l.getTime()>0?l.getTime():System.currentTimeMillis(),l.hasAccuracy()?l.getAccuracy():8);drawRemaining(s);if(guideDistance!=null)guideDistance.setText(formatDistance(s.remainingM)+"\nRESTANT");if(guideProgress!=null)guideProgress.setText(s.progressPercent+" %\nPROGRESSION");if(guideTitle!=null)guideTitle.setText(s.finished?"Tournée terminée":s.offRoute?"Rejoins le tracé":"Suis les flèches");if(guideSubtitle!=null)guideSubtitle.setText(s.finished?"La tournée est terminée.":s.offRoute?"Progression conservée • rapproche-toi de la ligne":"Guidage actif • le tracé parcouru disparaît derrière toi");followCamera(l);}
    private void drawRemaining(GuidanceEngine.State state){if(!guiding||guidingRoute==null)return;boolean erase=prefs.getBoolean("erase_passed",true);int start=!erase||state==null?0:Math.max(0,Math.min(guidingRoute.points.size()-2,state.nearestIndex));List<GeoPoint> pts=new ArrayList<>();if(state!=null&&erase&&Double.isFinite(state.position.lat))pts.add(new GeoPoint(state.position.lat,state.position.lon));for(int i=start+(erase?1:0);i<guidingRoute.points.size();i++){RouteStore.Point p=guidingRoute.points.get(i);pts.add(new GeoPoint(p.lat,p.lon));}remainingLine.setPoints(pts);remainingLine.getOutlinePaint().setColor(routeColor());remainingLine.getOutlinePaint().setStrokeWidth(dp(prefs.getInt("route_width",10)));if(!approachingStart){if(prefs.getBoolean("route_arrows",true))routeArrows.setPoints(pts);else routeArrows.setPoints(new ArrayList<>());}map.invalidate();}
    private void redrawGuidance(){if(approachingStart&&lastLocation!=null)updateApproachGuidance(lastLocation);else drawRemaining(null);}
    private void resumeGuidanceHere(){if(!guiding||guidance==null||lastLocation==null){toast("GPS en attente");return;}if(lastLocation.hasAccuracy()&&lastLocation.getAccuracy()>45){toast("Attends une position GPS plus précise");return;}if(!guidance.reposition(lastLocation.getLatitude(),lastLocation.getLongitude())){toast("Rapproche-toi du tracé");return;}approachingStart=false;guidanceStartResolved=true;clearApproachRoute();guidanceCameraFollow=true;toast("Guidage repris au point le plus proche");showTab("map",false);updateRouteGuidance(lastLocation);}
    private void stopGuidance(){press(contentHost);guidanceSession++;guiding=false;approachingStart=false;guidance=null;guidingRoute=null;clearApproachRoute();remainingLine.setPoints(new ArrayList<>());routeArrows.setPoints(new ArrayList<>());showTab("map",false);}
    private void followCamera(Location l){if(!guiding||!guidanceCameraFollow||!prefs.getBoolean("guidance_follow",true)||l==null)return;map.getController().animateTo(new GeoPoint(l.getLatitude(),l.getLongitude()));map.getController().setZoom(prefs.getInt("recenter_zoom",18)+.1);}

    @Override public void onLocationChanged(@NonNull Location l){lastLocation=l;if(headerSpeed!=null)headerSpeed.update(l);addRecordingFix(l,false);if(guiding){if(!guidanceStartResolved)resolveGuidanceStart(l);else if(approachingStart)updateApproachGuidance(l);else updateRouteGuidance(l);}}
    private void ensureLocation(){if(ContextCompat.checkSelfPermission(this,Manifest.permission.ACCESS_FINE_LOCATION)!=PackageManager.PERMISSION_GRANTED){ActivityCompat.requestPermissions(this,new String[]{Manifest.permission.ACCESS_FINE_LOCATION,Manifest.permission.ACCESS_COARSE_LOCATION},LOCATION_PERMISSION);return;}try{me.enableMyLocation();lm.requestLocationUpdates(LocationManager.GPS_PROVIDER,800,1.0f,this);if(lm.isProviderEnabled(LocationManager.NETWORK_PROVIDER))lm.requestLocationUpdates(LocationManager.NETWORK_PROVIDER,2200,4,this);}catch(Exception ignored){}}
    @Override public void onRequestPermissionsResult(int r,@NonNull String[] p,@NonNull int[] g){super.onRequestPermissionsResult(r,p,g);if(r==LOCATION_PERMISSION&&g.length>0&&g[0]==PackageManager.PERMISSION_GRANTED)ensureLocation();}
    private void recenter(){if(lastLocation==null){toast("GPS en attente");return;}map.getController().animateTo(new GeoPoint(lastLocation.getLatitude(),lastLocation.getLongitude()));map.getController().setZoom(prefs.getInt("recenter_zoom",18)+.2);}

    private LinearLayout page(String title,String sub){LinearLayout p=new LinearLayout(this);p.setOrientation(LinearLayout.VERTICAL);int pad=prefs.getBoolean("compact_ui",false)?13:17;p.setPadding(dp(pad),dp(prefs.getBoolean("compact_ui",false)?12:18),dp(pad),dp(28));p.addView(text(title,30,Typeface.BOLD,TEXT));TextView s=text(sub,12,Typeface.NORMAL,MUTED);s.setPadding(0,dp(4),0,dp(14));p.addView(s);return p;}
    private TextView section(String s){TextView t=text(s.toUpperCase(Locale.ROOT),10,Typeface.BOLD,accent);t.setPadding(0,dp(20),0,dp(8));return t;}
    private TextView text(String s,float size,int style,int color){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);t.setTypeface(Typeface.create("sans-serif",style));t.setIncludeFontPadding(false);return t;}
    private TextView pill(String s,int color){TextView t=text(s,13,Typeface.BOLD,(color==accent||color==GREEN||color==PEACH||color==RED)?BG:TEXT);t.setGravity(Gravity.CENTER);t.setBackground(glass(color,20));t.setElevation(dp(2));return t;}
    private TextView metric(String value,String label){TextView t=text(value+"\n"+label,13,Typeface.BOLD,TEXT);t.setGravity(Gravity.CENTER);t.setBackground(glass(SURFACE,20));return t;}
    private TextView bigMetric(String value,String label,int color){TextView t=text(value+"\n"+label,18,Typeface.BOLD,TEXT);t.setGravity(Gravity.CENTER);t.setBackground(glass(Color.argb(160,Color.red(color),Color.green(color),Color.blue(color)),24));return t;}
    private TextView icon(String s){TextView t=text(s,19,Typeface.BOLD,TEXT);t.setGravity(Gravity.CENTER);t.setBackground(glass(SURFACE2,18));return t;}
    private TextView infoCard(String title,String body){TextView t=text(title+"\n"+body,12,Typeface.NORMAL,MUTED);t.setPadding(dp(14),dp(12),dp(14),dp(12));t.setBackground(glass(SURFACE,20));return t;}
    private View stage(String number,String title,String sub,int color){LinearLayout r=new LinearLayout(this);r.setGravity(Gravity.CENTER_VERTICAL);r.setPadding(dp(12),dp(10),dp(12),dp(10));r.setBackground(glass(SURFACE,18));TextView n=text(number,12,Typeface.BOLD,color);n.setGravity(Gravity.CENTER);n.setBackground(glass(SURFACE2,14));r.addView(n,new LinearLayout.LayoutParams(dp(42),dp(42)));LinearLayout tx=new LinearLayout(this);tx.setOrientation(LinearLayout.VERTICAL);tx.setPadding(dp(11),0,0,0);tx.addView(text(title,13,Typeface.BOLD,TEXT));tx.addView(text(sub,11,Typeface.NORMAL,MUTED));r.addView(tx,new LinearLayout.LayoutParams(0,-2,1));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.topMargin=dp(7);r.setLayoutParams(lp);return r;}
    private View summaryStat(String label,String value){LinearLayout c=new LinearLayout(this);c.setOrientation(LinearLayout.VERTICAL);c.setGravity(Gravity.CENTER);c.addView(text(value,13,Typeface.BOLD,TEXT));c.addView(text(label,9,Typeface.BOLD,MUTED));return c;}
    private GradientDrawable glass(int color,float radius){int base=prefs==null?84:prefs.getInt("glass_alpha",84);String style=prefs==null?"apple":prefs.getString("ui_style","apple");if("contrast".equals(style))base=Math.min(98,base+10);if("minimal".equals(style))radius*=.78f;int aa=Math.max(38,Math.min(100,base))*255/100;int c1=Color.argb(Math.min(255,aa+20),Color.red(color),Color.green(color),Color.blue(color));int c2=Color.argb(aa,Color.red(color),Color.green(color),Color.blue(color));GradientDrawable g=new GradientDrawable(GradientDrawable.Orientation.TOP_BOTTOM,new int[]{c1,c2});g.setCornerRadius(dp(radius));g.setStroke(dp(1),Color.argb("contrast".equals(style)?70:42,255,255,255));return g;}
    private void press(View v){if(v==null)return;if(prefs.getBoolean("haptics",true))v.performHapticFeedback(HapticFeedbackConstants.KEYBOARD_TAP);if(prefs.getBoolean("animations",true))v.animate().scaleX(.94f).scaleY(.94f).setDuration(70).withEndAction(()->v.animate().scaleX(1).scaleY(1).setDuration(150).start()).start();}
    private int animDuration(){return prefs.getInt("anim_speed",220);}
    private int routeColor(){return prefs.getInt("route_color",BLUE);}
    private void toast(String s){Toast.makeText(this,s,Toast.LENGTH_SHORT).show();}
    private int dp(float v){return Math.round(v*getResources().getDisplayMetrics().density);}
    private static String formatDistance(double m){return m<1000?Math.round(m)+" m":String.format(Locale.FRANCE,"%.1f km",m/1000d);}
    private static String formatMinutes(int m){return String.format(Locale.FRANCE,"%dh%02d",m/60,m%60);}
    private static String formatDuration(long ms){long min=Math.max(0,ms/60000);return String.format(Locale.FRANCE,"%dh%02d",min/60,min%60);}
    private static String formatDate(long ms){return new SimpleDateFormat("dd MMM yyyy • HH:mm",Locale.FRANCE).format(new Date(ms));}
    private static String timeLabel(int minutes){int m=((minutes%1440)+1440)%1440;return String.format(Locale.FRANCE,"%02d:%02d",m/60,m%60);}
    private static int parsePositive(String s){try{return Math.max(0,Integer.parseInt(s.trim()));}catch(Exception e){return 0;}}
    private static int parseClock(String raw){if(raw==null)return-1;String s=raw.trim().replace("h",":").replace("H",":");try{int h,m;if(s.contains(":")){String[] p=s.split(":");if(p.length<2)return-1;h=Integer.parseInt(p[0]);m=Integer.parseInt(p[1]);}else{String d=s.replaceAll("[^0-9]","");if(d.length()<3||d.length()>4)return-1;int v=Integer.parseInt(d);h=v/100;m=v%100;}return h>=0&&h<24&&m>=0&&m<60?h*60+m:-1;}catch(Exception e){return-1;}}
    private static int nowMinutes(){Calendar c=Calendar.getInstance();return c.get(Calendar.HOUR_OF_DAY)*60+c.get(Calendar.MINUTE);}
    private static String todayKey(){return new SimpleDateFormat("yyyy-MM-dd",Locale.FRANCE).format(new Date());}
    private static String dayLabel(String date){try{return new SimpleDateFormat("EEEE d MMMM",Locale.FRANCE).format(new SimpleDateFormat("yyyy-MM-dd",Locale.FRANCE).parse(date));}catch(Exception e){return date;}}
    private static String monthLabel(String month){try{return new SimpleDateFormat("MMMM yyyy",Locale.FRANCE).format(new SimpleDateFormat("yyyy-MM",Locale.FRANCE).parse(month));}catch(Exception e){return month;}}

    private void rebuildChrome(){if(root==null)return;if(topBar!=null)root.removeView(topBar);if(dock!=null)root.removeView(dock);topBar=buildTopBar();dock=buildDock();root.addView(topBar);root.addView(dock);topBar.bringToFront();contentHost.bringToFront();dock.bringToFront();updateDock();positionChrome();applyRuntimePrefs();}
    private void applyRuntimePrefs(){if(prefs.getBoolean("keep_screen",true))getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);else getWindow().clearFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);if(mapLogo!=null)mapLogo.setVisibility("map".equals(selectedTab)&&prefs.getBoolean("map_logo",true)?View.VISIBLE:View.GONE);if(headerSpeed!=null)headerSpeed.setVisibility(prefs.getBoolean("show_speed",true)?View.VISIBLE:View.GONE);}
    private void positionChrome(){if(root==null||topBar==null||dock==null||contentHost==null)return;boolean compact=prefs.getBoolean("compact_ui",false);int top=systemTop+dp(8),bottom=systemBottom+dp(8),topH=dp(compact?58:64),dockH=dp(compact?62:70);FrameLayout.LayoutParams hp=new FrameLayout.LayoutParams(-1,topH,Gravity.TOP);hp.setMargins(dp(10),top,dp(10),0);topBar.setLayoutParams(hp);FrameLayout.LayoutParams dpv=new FrameLayout.LayoutParams(-1,dockH,Gravity.BOTTOM);dpv.setMargins(dp(10),0,dp(10),bottom);dock.setLayoutParams(dpv);if(mapLogo!=null){FrameLayout.LayoutParams ml=new FrameLayout.LayoutParams(dp(52),dp(52),Gravity.TOP|Gravity.START);ml.setMargins(dp(14),top+topH+dp(10),0,0);mapLogo.setLayoutParams(ml);}if("map".equals(selectedTab)){FrameLayout.LayoutParams cp=new FrameLayout.LayoutParams(-1,-2,Gravity.BOTTOM);cp.setMargins(dp(10),0,dp(10),bottom+dockH+dp(8));contentHost.setLayoutParams(cp);}else{FrameLayout.LayoutParams cp=new FrameLayout.LayoutParams(-1,-1);cp.setMargins(0,top+topH+dp(8),0,bottom+dockH+dp(8));contentHost.setLayoutParams(cp);}}

    @Override protected void onResume(){super.onResume();if(map!=null)map.onResume();}
    @Override protected void onPause(){super.onPause();if(map!=null)map.onPause();if(recording)store.saveDraft(recordingPoints,recordingEvents,recordingStarted);}
    @Override protected void onDestroy(){guidanceSession++;try{lm.removeUpdates(this);}catch(Exception ignored){}if(me!=null)me.disableMyLocation();if(map!=null)map.onDetach();super.onDestroy();}
    @Override public void onProviderEnabled(@NonNull String provider){} @Override public void onProviderDisabled(@NonNull String provider){}
